SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS `retiros_respaldo`;
CREATE TABLE `retiros_respaldo` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `investor_id` bigint unsigned DEFAULT NULL,
  `user_id` bigint unsigned NOT NULL,
  `origen` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'inversion',
  `tipo` enum('rendimiento','capital','bono') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `monto` decimal(15,2) NOT NULL,
  `impuesto` decimal(15,2) NOT NULL,
  `monto_neto` decimal(15,2) NOT NULL,
  `fecha_solicitud` date NOT NULL,
  `fecha_retiro` date DEFAULT NULL,
  `estado` enum('pendiente','aprobado','procesado','rechazado','cancelado') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pendiente',
  `metodo_pago` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `banco` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tipo_cuenta` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `numero_cuenta` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `observaciones` text COLLATE utf8mb4_unicode_ci,
  `motivo_rechazo` text COLLATE utf8mb4_unicode_ci,
  `aprobado_por` bigint unsigned DEFAULT NULL,
  `fecha_aprobacion` timestamp NULL DEFAULT NULL,
  `procesado_por` bigint unsigned DEFAULT NULL,
  `fecha_procesamiento` timestamp NULL DEFAULT NULL,
  `comprobante_pago` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `receipt_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `retiros_investor_id_foreign` (`investor_id`),
  KEY `retiros_user_id_foreign` (`user_id`),
  KEY `retiros_aprobado_por_foreign` (`aprobado_por`),
  KEY `retiros_procesado_por_foreign` (`procesado_por`),
  KEY `retiros_origen_index` (`origen`)
) ENGINE=InnoDB AUTO_INCREMENT=7031 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
